25	    // Chipmunk-style filter semantics applied on top of the broad query:
26	    // shapes sharing a non-zero group never collide, otherwise both
27	    // category/mask tests must pass.
28	    bool rayCastPassesFilter(const RayCastInput& input, PhysicsShape* shape)
29	    {
30	        if (shape == nullptr)
31	        {
32	            return false;
33	        }
34	
35	        if (input.groupFilter != 0 && shape->getGroup() == input.groupFilter)
36	        {
37	            return false;
38	        }
39	
40	        if ((static_cast<unsigned int>(shape->getCategoryBitmask()) & input.collisionMask) == 0)
41	        {
42	            return false;
43	        }
44	
45	        if ((input.categoryMask & static_cast<unsigned int>(shape->getCollisionBitmask())) == 0)
46	        {
47	            return false;
48	        }
49	
50	        return true;
51	    }
52	
53	    // Context used by PhysicsRayCast::rayCastAllCallback.
54	    struct RayCastAllContext
55	    {
56	        RayCastHit* hits;
57	        int maxHits;
58	        int count;
59	        Vec2 origin;
60	    };
61	
62	    void fillRayCastHit(PhysicsShape* shape, const Vec2& point, const Vec2& normal,
63	                        float alpha, const Vec2& origin, float maxDistance, RayCastHit* outHit)
64	    {
65	        outHit->shape = shape;
66	        outHit->body = shape != nullptr ? shape->getBody() : nullptr;
67	        outHit->point = point;
68	        outHit->normal = normal;
69	        outHit->fraction = alpha;
70	        outHit->distance = alpha * maxDistance;
71	        (void)origin;
72	    }
73	}
