90	bool PhysicsRayCast::init(PhysicsWorld* world)
91	{
92	    if (world == nullptr)
93	    {
94	        return false;
95	    }
96	
97	    _world = world;
98	
99	    // Resolve the underlying cpSpace from any simulated body. It is fine for
100	    // the space to stay null on an empty world: every query falls back to the
101	    // PhysicsWorld public API in that case.
102	    _space = nullptr;
103	    for (auto body : world->getAllBodies())
104	    {
105	        if (body != nullptr && body->getCPBody() != nullptr)
106	        {
107	            cpSpace* space = cpBodyGetSpace(body->getCPBody());
108	            if (space != nullptr)
109	            {
110	                _space = space;
111	                break;
112	            }
113	        }
114	    }
115	
116	    _initialized = true;
117	    return true;
118	}
