120	bool PhysicsRayCast::rayCastFirst(const RayCastInput& input, RayCastHit* outHit)
121	{
122	    if (!_initialized || _world == nullptr)
123	    {
124	        return false;
125	    }
126	
127	    Vec2 dir = input.direction;
128	    float length = dir.getLength();
129	    if (length <= 0.0f)
130	    {
131	        return false;
132	    }
133	    dir = dir / length;
134	
135	    float maxDistance = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
136	    Vec2 end = input.origin + dir * maxDistance;
137	
138	    bool found = false;
139	    RayCastHit best;
140	    best.fraction = FLT_MAX;
141	
142	    PhysicsRayCastCallbackFunc func = [&](PhysicsWorld& /*world*/, const PhysicsRayCastInfo& info, void* /*data*/) -> bool
143	    {
144	        if (rayCastPassesFilter(input, info.shape) && info.fraction < best.fraction)
145	        {
146	            fillRayCastHit(info.shape, info.contact, info.normal, info.fraction,
147	                           input.origin, maxDistance, &best);
148	            found = true;
149	        }
150	        return true;
151	    };
152	    _world->rayCast(func, input.origin, end, nullptr);
153	
154	    if (found && outHit != nullptr)
155	    {
156	        *outHit = best;
157	    }
158	    return found;
159	}
