161	int PhysicsRayCast::rayCastAll(const RayCastInput& input, RayCastHit* outHits, int maxHits)
162	{
163	    if (!_initialized || _world == nullptr || outHits == nullptr || maxHits <= 0)
164	    {
165	        return 0;
166	    }
167	
168	    Vec2 dir = input.direction;
169	    float length = dir.getLength();
170	    if (length <= 0.0f)
171	    {
172	        return 0;
173	    }
174	    dir = dir / length;
175	
176	    float maxDistance = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
177	    Vec2 end = input.origin + dir * maxDistance;
178	
179	    std::vector<RayCastHit> collected;
180	
181	    PhysicsRayCastCallbackFunc func = [&](PhysicsWorld& /*world*/, const PhysicsRayCastInfo& info, void* /*data*/) -> bool
182	    {
183	        if (rayCastPassesFilter(input, info.shape))
184	        {
185	            RayCastHit hit;
186	            fillRayCastHit(info.shape, info.contact, info.normal, info.fraction,
187	                           input.origin, maxDistance, &hit);
188	            collected.push_back(hit);
189	        }
190	        return true;
191	    };
192	    _world->rayCast(func, input.origin, end, nullptr);
193	
194	    std::sort(collected.begin(), collected.end(),
195	              [](const RayCastHit& a, const RayCastHit& b) { return a.fraction < b.fraction; });
196	
197	    int count = std::min(static_cast<int>(collected.size()), maxHits);
198	    for (int i = 0; i < count; ++i)
199	    {
200	        outHits[i] = collected[i];
201	    }
202	    return count;
203	}
