205	bool PhysicsRayCast::rayCastAny(const RayCastInput& input)
206	{
207	    if (!_initialized || _world == nullptr)
208	    {
209	        return false;
210	    }
211	
212	    Vec2 dir = input.direction;
213	    float length = dir.getLength();
214	    if (length <= 0.0f)
215	    {
216	        return false;
217	    }
218	    dir = dir / length;
219	
220	    float maxDistance = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
221	    Vec2 end = input.origin + dir * maxDistance;
222	
223	    bool found = false;
224	    PhysicsRayCastCallbackFunc func = [&](PhysicsWorld& /*world*/, const PhysicsRayCastInfo& info, void* /*data*/) -> bool
225	    {
226	        if (rayCastPassesFilter(input, info.shape))
227	        {
228	            found = true;
229	            return false; // stop the query at the first matching shape
230	        }
231	        return true;
232	    };
233	    _world->rayCast(func, input.origin, end, nullptr);
234	
235	    return found;
236	}
