262	int PhysicsRayCast::fanRayCast(const Vec2& origin, const Vec2& direction, float angle, int numRays,
263	                               float maxDistance, RayCastHit* outHits, int maxHits)
264	{
265	    if (outHits == nullptr || maxHits <= 0 || numRays <= 0)
266	    {
267	        return 0;
268	    }
269	
270	    float baseAngle = std::atan2(direction.y, direction.x);
271	    float halfFan = angle * 0.5f;
272	
273	    int count = 0;
274	    for (int i = 0; i < numRays && count < maxHits; ++i)
275	    {
276	        float t = numRays > 1 ? static_cast<float>(i) / static_cast<float>(numRays - 1) : 0.5f;
277	        float rayAngle = baseAngle - halfFan + angle * t;
278	
279	        RayCastInput input;
280	        input.origin = origin;
281	        input.direction = Vec2(std::cos(rayAngle), std::sin(rayAngle));
282	        input.maxDistance = maxDistance;
283	        input.categoryMask = _defaultCategoryMask;
284	        input.collisionMask = _defaultCollisionMask;
285	        input.groupFilter = _defaultGroup;
286	
287	        RayCastHit hit;
288	        if (rayCastFirst(input, &hit))
289	        {
290	            outHits[count++] = hit;
291	        }
292	    }
293	    return count;
294	}
