296	int PhysicsRayCast::circleRayCast(const Vec2& center, float radius, int numRays,
297	                                  RayCastHit* outHits, int maxHits)
298	{
299	    if (outHits == nullptr || maxHits <= 0 || numRays <= 0)
300	    {
301	        return 0;
302	    }
303	
304	    int count = 0;
305	    for (int i = 0; i < numRays && count < maxHits; ++i)
306	    {
307	        float rayAngle = static_cast<float>(i) * 2.0f * static_cast<float>(M_PI) / static_cast<float>(numRays);
308	
309	        RayCastInput input;
310	        input.origin = center;
311	        input.direction = Vec2(std::cos(rayAngle), std::sin(rayAngle));
312	        input.maxDistance = radius;
313	        input.categoryMask = _defaultCategoryMask;
314	        input.collisionMask = _defaultCollisionMask;
315	        input.groupFilter = _defaultGroup;
316	
317	        RayCastHit hit;
318	        if (rayCastFirst(input, &hit))
319	        {
320	            outHits[count++] = hit;
321	        }
322	    }
323	    return count;
324	}
