326	bool PhysicsRayCast::lineOfSight(const Vec2& from, const Vec2& to, unsigned int obstacleMask)
327	{
328	    RayCastInput input;
329	    input.origin = from;
330	    input.direction = to - from;
331	    input.maxDistance = input.direction.getLength();
332	    input.categoryMask = 0xFFFFFFFF;
333	    input.collisionMask = obstacleMask;
334	    input.groupFilter = 0;
335	
336	    // Line of sight is clear only when no obstacle is hit along the segment.
337	    return !rayCastAny(input);
338	}
