370	float PhysicsRayCast::computeReflectionAngle(const Vec2& inDirection, const Vec2& normal)
371	{
372	    Vec2 n = normal.getNormalized();
373	    Vec2 reflected = computeReflectionDirection(inDirection, normal);
374	    float dot = clampf(Vec2::dot(reflected, n), -1.0f, 1.0f);
375	    return std::acos(dot);
376	}
377	
378	Vec2 PhysicsRayCast::computeReflectionDirection(const Vec2& inDirection, const Vec2& normal)
379	{
380	    Vec2 d = inDirection.getNormalized();
381	    Vec2 n = normal.getNormalized();
382	    if (d.isZero() || n.isZero())
383	    {
384	        return Vec2::ZERO;
385	    }
386	    // r = d - 2 * (d . n) * n
387	    return d - n * (2.0f * Vec2::dot(d, n));
388	}
389	
390	Vec2 PhysicsRayCast::computeRefractionDirection(const Vec2& inDirection, const Vec2& normal, float ratio)
391	{
392	    Vec2 d = inDirection.getNormalized();
393	    Vec2 n = normal.getNormalized();
394	    if (d.isZero() || n.isZero())
395	    {
396	        return Vec2::ZERO;
397	    }
398	
399	    float cosI = -Vec2::dot(d, n);
400	    float k = 1.0f - ratio * ratio * (1.0f - cosI * cosI);
401	    if (k < 0.0f)
402	    {
403	        // Total internal reflection: no refracted ray exists.
404	        return Vec2::ZERO;
405	    }
406	    return d * ratio + n * (ratio * cosI - std::sqrt(k));
407	}
