409	void PhysicsRayCast::rayCastAllCallback(cpShape* shape, cpVect point, cpVect normal,
410	                                        cpFloat alpha, void* data)
411	{
412	    auto* context = static_cast<RayCastAllContext*>(data);
413	    if (context == nullptr || context->hits == nullptr || context->count >= context->maxHits)
414	    {
415	        return;
416	    }
417	
418	    PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
419	    if (physicsShape == nullptr)
420	    {
421	        return;
422	    }
423	
424	    RayCastHit* hit = &context->hits[context->count++];
425	    hit->shape = physicsShape;
426	    hit->body = physicsShape->getBody();
427	    hit->point = PhysicsHelper::cpv2point(point);
428	    hit->normal = PhysicsHelper::cpv2point(normal);
429	    hit->fraction = static_cast<float>(alpha);
430	    hit->distance = hit->point.distance(context->origin);
431	}
