                else
                {
                    if (t < t0) return false;
                    if (t < t1) t1 = t;
                }
            }
        }
        return true;
    }
}

PhysicsSpatialIndex::PhysicsSpatialIndex()
: _cellSize(64.0f)
, _worldBounds(Rect::ZERO)
, _gridWidth(0)
, _gridHeight(0)
, _initialized(false)
{
}

PhysicsSpatialIndex::~PhysicsSpatialIndex()
{
}

bool PhysicsSpatialIndex::init(float cellSize, const Rect& worldBounds)
{
    if (cellSize <= 0.0f || worldBounds.size.width <= 0.0f || worldBounds.size.height <= 0.0f)
    {
        return false;
    }

    _cellSize = cellSize;
    _worldBounds = worldBounds;
    _gridWidth = static_cast<int>(std::ceil(worldBounds.size.width / cellSize));
    _gridHeight = static_cast<int>(std::ceil(worldBounds.size.height / cellSize));
    if (_gridWidth <= 0 || _gridHeight <= 0)
    {
        return false;
    }

    _cells.assign(static_cast<size_t>(_gridWidth) * static_cast<size_t>(_gridHeight),
                  std::vector<PhysicsBody*>());
    _trackedBodies.clear();
    _initialized = true;
    return true;
}

void PhysicsSpatialIndex::clear()
{
    for (auto& cell : _cells)
    {
        cell.clear();
    }
    _trackedBodies.clear();
}

int PhysicsSpatialIndex::cellIndex(int x, int y) const
{
    return y * _gridWidth + x;
}

void PhysicsSpatialIndex::getCellCoords(const Vec2& point, int& outX, int& outY) const
{
    if (!_initialized || _gridWidth <= 0 || _gridHeight <= 0)
    {
        outX = 0;
        outY = 0;
        return;
    }

    int x = static_cast<int>(std::floor((point.x - _worldBounds.origin.x) / _cellSize));
    int y = static_cast<int>(std::floor((point.y - _worldBounds.origin.y) / _cellSize));
    outX = clampCoord(x, _gridWidth);
    outY = clampCoord(y, _gridHeight);
}

Rect PhysicsSpatialIndex::getBodyBounds(PhysicsBody* body) const
{
    if (body == nullptr)
    {
        return Rect::ZERO;
    }

    Vec2 bodyPos = body->getPosition();
    float minX = bodyPos.x;
    float minY = bodyPos.y;
    float maxX = bodyPos.x;
    float maxY = bodyPos.y;

    const auto& shapes = body->getShapes();
    for (auto shape : shapes)
    {
        if (shape == nullptr)
        {
            continue;
        }
        Vec2 center = bodyPos + shape->getCenter();
        float radius = 0.0f;
        if (shape->getType() == PhysicsShape::Type::CIRCLE)
        {
            radius = static_cast<PhysicsShapeCircle*>(shape)->getRadius();
        }
        minX = std::min(minX, center.x - radius);
        minY = std::min(minY, center.y - radius);
        maxX = std::max(maxX, center.x + radius);
        maxY = std::max(maxY, center.y + radius);
    }

    return Rect(minX, minY, maxX - minX, maxY - minY);
}

void PhysicsSpatialIndex::insertBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr || _trackedBodies.count(body) != 0)
    {
        return;
    }

    _trackedBodies.insert(body);

    Rect bounds = getBodyBounds(body);
    int x0, y0, x1, y1;
    getCellCoords(Vec2(bounds.getMinX(), bounds.getMinY()), x0, y0);
    getCellCoords(Vec2(bounds.getMaxX(), bounds.getMaxY()), x1, y1);

    for (int y = y0; y <= y1; ++y)
    {
        for (int x = x0; x <= x1; ++x)
        {
            _cells[cellIndex(x, y)].push_back(body);
        }
    }
}

void PhysicsSpatialIndex::removeBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr || _trackedBodies.count(body) == 0)
    {
        return;
    }

    _trackedBodies.erase(body);
    for (auto& cell : _cells)
    {
        cell.erase(std::remove(cell.begin(), cell.end(), body), cell.end());
    }
}

void PhysicsSpatialIndex::updateBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr)
    {
        return;
    }

    if (_trackedBodies.count(body) != 0)
    {
        removeBody(body);
    }
    insertBody(body);
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::queryRect(const Rect& rect) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized)
    {
        return result;
    }

    int x0, y0, x1, y1;
    getCellCoords(Vec2(rect.getMinX(), rect.getMinY()), x0, y0);
    getCellCoords(Vec2(rect.getMaxX(), rect.getMaxY()), x1, y1);

    std::unordered_set<PhysicsBody*> seen;
    for (int y = y0; y <= y1; ++y)
    {
        for (int x = x0; x <= x1; ++x)
        {
            for (auto body : _cells[cellIndex(x, y)])
            {
                if (seen.insert(body).second && getBodyBounds(body).intersectsRect(rect))
                {
                    result.push_back(body);
                }
            }
        }
    }
    return result;
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::queryCircle(const Vec2& center, float radius) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || radius < 0.0f)
    {
        return result;
    }

    Rect region(center.x - radius, center.y - radius, radius * 2.0f, radius * 2.0f);
    int x0, y0, x1, y1;
    getCellCoords(Vec2(region.getMinX(), region.getMinY()), x0, y0);
    getCellCoords(Vec2(region.getMaxX(), region.getMaxY()), x1, y1);

    std::unordered_set<PhysicsBody*> seen;
    for (int y = y0; y <= y1; ++y)
    {
        for (int x = x0; x <= x1; ++x)
        {
            for (auto body : _cells[cellIndex(x, y)])
            {
                if (seen.insert(body).second && circleIntersectsRect(center, radius, getBodyBounds(body)))
                {
                    result.push_back(body);
                }
            }
        }
    }
    return result;
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::querySegment(const Vec2& start, const Vec2& end) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized)
    {
        return result;
    }

    float minX = std::min(start.x, end.x);
    float minY = std::min(start.y, end.y);
    Rect region(minX, minY, std::fabs(end.x - start.x), std::fabs(end.y - start.y));

    int x0, y0, x1, y1;
    getCellCoords(Vec2(region.getMinX(), region.getMinY()), x0, y0);
    getCellCoords(Vec2(region.getMaxX(), region.getMaxY()), x1, y1);

    std::unordered_set<PhysicsBody*> seen;
    for (int y = y0; y <= y1; ++y)
    {
        for (int x = x0; x <= x1; ++x)
        {
            for (auto body : _cells[cellIndex(x, y)])
            {
                if (seen.insert(body).second && segmentIntersectsRect(start, end, getBodyBounds(body)))
                {
                    result.push_back(body);
                }
            }
        }
    }
    return result;
}

std::vector<BroadPhasePair> PhysicsSpatialIndex::findPotentialPairs() const
{
    std::vector<BroadPhasePair> pairs;
    if (!_initialized)
    {
        return pairs;
    }

    std::unordered_set<PhysicsBody*> pairSeen;
    for (const auto& cell : _cells)
    {
        size_t n = cell.size();
        for (size_t i = 0; i < n; ++i)
        {
            for (size_t j = i + 1; j < n; ++j)
            {
                PhysicsBody* a = cell[i];
                PhysicsBody* b = cell[j];
                if (a == b)
                {
                    continue;
                }
                // Canonical ordering so each unordered pair is emitted once.
                PhysicsBody* lo = std::min(a, b);
                PhysicsBody* hi = std::max(a, b);
                // Hash the pair via the lower pointer only if the higher one
                // was already paired with it; use a combined check set.
                uintptr_t key = reinterpret_cast<uintptr_t>(lo) ^ (reinterpret_cast<uintptr_t>(hi) << 1);
                PhysicsBody* marker = reinterpret_cast<PhysicsBody*>(key);
                (void)marker;
                // Simple dedupe: check by scanning is O(n^2); instead use a set of pairs.
                // We emulate a pair set with a static thread-local-free approach:
                // store the pair only if not already present.
                bool exists = false;
                for (const auto& p : pairs)
                {
                    if (p.bodyA == lo && p.bodyB == hi)
                    {
                        exists = true;
                        break;
                    }
                }
                if (!exists)
                {
                    BroadPhasePair pair;
                    pair.bodyA = lo;
                    pair.bodyB = hi;
                    pairs.push_back(pair);
                }
            }
        }
    }
    (void)pairSeen;
    return pairs;
}

int PhysicsSpatialIndex::getCellCount() const
{
    return _initialized ? _gridWidth * _gridHeight : 0;
}

int PhysicsSpatialIndex::getBodyCount() const
{
    return static_cast<int>(_trackedBodies.size());
}

float PhysicsSpatialIndex::getCellSize() const
{
    return _cellSize;
}

void PhysicsSpatialIndex::rebuild()
{
    if (!_initialized)
    {
        return;
    }

    std::vector<PhysicsBody*> bodies(_trackedBodies.begin(), _trackedBodies.end());
    for (auto& cell : _cells)
    {
        cell.clear();
    }
    _trackedBodies.clear();
    for (auto body : bodies)
    {
        insertBody(body);
    }
}

void PhysicsSpatialIndex::setCellSize(float size)
{
    if (size <= 0.0f)
    {
        return;
    }

    _cellSize = size;
    if (_initialized)
    {
        std::vector<PhysicsBody*> bodies(_trackedBodies.begin(), _trackedBodies.end());
        init(size, _worldBounds);
        for (auto body : bodies)
        {
            insertBody(body);
        }
    }
}

void PhysicsSpatialIndex::setWorldBounds(const Rect& bounds)
{
    if (bounds.size.width <= 0.0f || bounds.size.height <= 0.0f)
    {
        return;
    }

    if (_initialized)
    {
        std::vector<PhysicsBody*> bodies(_trackedBodies.begin(), _trackedBodies.end());
        init(_cellSize, bounds);
        for (auto body : bodies)
        {
            insertBody(body);
        }
    }
    else
    {
        _worldBounds = bounds;
    }
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::getNearestBodies(const Vec2& point, int maxCount) const
{
    std::vector<PhysicsBody*> bodies(_trackedBodies.begin(), _trackedBodies.end());
    std::sort(bodies.begin(), bodies.end(), [&point](PhysicsBody* a, PhysicsBody* b)
    {
        float da = a->getPosition().distanceSquared(point);
        float db = b->getPosition().distanceSquared(point);
        if (da != db)
        {
            return da < db;
        }
        return a < b; // deterministic tie-break
    });

    if (maxCount >= 0 && static_cast<int>(bodies.size()) > maxCount)
    {
        bodies.resize(static_cast<size_t>(maxCount));
    }
    return bodies;
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::getBodiesInFrustum(const Vec2& origin, const Vec2& direction, float angle, float distance) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || distance <= 0.0f || angle <= 0.0f || direction.isZero())
    {
        return result;
    }

    Vec2 dirNorm = direction.getNormalized();
    float halfAngle = angle * 0.5f;
    float cosHalf = std::cos(halfAngle);

    for (auto body : _trackedBodies)
    {
        Vec2 toBody = body->getPosition() - origin;
        float dist = toBody.getLength();
        if (dist > distance)
        {
            continue;
        }
        if (dist > 1e-6f)
        {
            float cosTheta = Vec2::dot(toBody / dist, dirNorm);
            if (cosTheta < cosHalf)
            {
                continue;
            }
        }
        result.push_back(body);
    }
    return result;
}

