 ****************************************************************************/

#include "physics/CCPhysicsShapeQuery.h"
#if CC_USE_PHYSICS

#include <cmath>
#include <cfloat>
#include <algorithm>
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsWorld.h"
#include "physics/CCPhysicsHelper.h"

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

NS_CC_BEGIN

namespace
{
    struct ShapeQueryContext
    {
        PhysicsShape* queryShape;
        ShapeQueryResult* results;
        int maxResults;
        int count;
    };

    void shapeQueryCallback(cpShape* shape, cpContactPointSet* points, void* data)
    {
        auto* context = static_cast<ShapeQueryContext*>(data);
        if (context == nullptr || context->count >= context->maxResults)
        {
            return;
        }

        PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
        if (physicsShape == nullptr || physicsShape == context->queryShape)
        {
            return;
        }

        ShapeQueryResult& result = context->results[context->count++];
        result.shape = physicsShape;
        result.pointCount = 0;
        result.normal = Vec2::ZERO;
        result.depth = 0.0f;

        if (points != nullptr)
        {
            int n = std::min(points->count, 4);
            for (int i = 0; i < n; ++i)
            {
                result.contactPoints[i] = PhysicsHelper::cpv2point(points->points[i].pointA);
                result.depth = std::max(result.depth, -static_cast<float>(points->points[i].distance));
            }
            result.pointCount = n;
            if (n > 0)
            {
                result.normal = PhysicsHelper::cpv2point(points->normal);
            }
        }
    }

    struct CollectShapesContext
    {
        PhysicsShape** results;
        int maxResults;
        int count;
    };

    void collectShapeCallback(cpShape* shape, void* data)
    {
        auto* context = static_cast<CollectShapesContext*>(data);
        if (context == nullptr || context->count >= context->maxResults)
        {
            return;
        }

        PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
        if (physicsShape != nullptr)
        {
            context->results[context->count++] = physicsShape;
        }
    }

    void collectSegmentCallback(cpShape* shape, cpVect /*point*/, cpVect /*normal*/, cpFloat /*alpha*/, void* data)
    {
        collectShapeCallback(shape, data);
    }

    void collectPointCallback(cpShape* shape, cpVect /*point*/, cpFloat /*distance*/, cpVect /*gradient*/, void* data)
    {
        collectShapeCallback(shape, data);
    }

    // Radius covering the shape for capsule-cast style sweep approximations.
    float shapeBoundingRadius(PhysicsShape* shape)
    {
        if (shape == nullptr)
        {
            return 0.0f;
        }
        if (shape->getType() == PhysicsShape::Type::CIRCLE)
        {
            return static_cast<PhysicsShapeCircle*>(shape)->getRadius();
        }
        cpBB bb = cpShapeGetBB(shape->getCPShape());
        cpVect c = cpBBCenter(bb);
        float rx = static_cast<float>(bb.r - c.x);
        float ry = static_cast<float>(bb.t - c.y);
        return std::sqrt(rx * rx + ry * ry);
    }
}

PhysicsShapeQuery::PhysicsShapeQuery()
: _world(nullptr)
, _space(nullptr)
, _initialized(false)
{
}

PhysicsShapeQuery::~PhysicsShapeQuery()
{
}

bool PhysicsShapeQuery::init(PhysicsWorld* world)
{
    if (world == nullptr)
    {
        return false;
    }

    _world = world;

    // Resolve the underlying cpSpace from any simulated body. It is fine for
    // the space to stay null on an empty world: space-level queries simply
    // report no hits in that case.
    _space = nullptr;
    for (auto body : world->getAllBodies())
    {
        if (body != nullptr && body->getCPBody() != nullptr)
        {
            cpSpace* space = cpBodyGetSpace(body->getCPBody());
            if (space != nullptr)
            {
                _space = space;
                break;
            }
        }
    }

    _initialized = true;
    return true;
}

bool PhysicsShapeQuery::overlapTest(PhysicsShape* shapeA, PhysicsShape* shapeB,
                                    Vec2* contactPoints, int* pointCount)
{
    if (!_initialized || shapeA == nullptr || shapeB == nullptr ||
        shapeA->getCPShape() == nullptr || shapeB->getCPShape() == nullptr)
    {
        return false;
    }

    cpContactPointSet points = cpShapesCollide(shapeA->getCPShape(), shapeB->getCPShape());

    if (pointCount != nullptr)
    {
        *pointCount = points.count;
    }
    if (contactPoints != nullptr)
    {
        int n = std::min(points.count, 4);
        for (int i = 0; i < n; ++i)
        {
            contactPoints[i] = PhysicsHelper::cpv2point(points.points[i].pointA);
        }
    }

    return points.count > 0;
}

int PhysicsShapeQuery::shapeQuery(PhysicsShape* shape, ShapeQueryResult* results, int maxResults)
{
    if (!_initialized || _space == nullptr || shape == nullptr ||
        shape->getCPShape() == nullptr || results == nullptr || maxResults <= 0)
    {
        return 0;
    }

    ShapeQueryContext context;
    context.queryShape = shape;
    context.results = results;
    context.maxResults = maxResults;
    context.count = 0;

    cpSpaceShapeQuery(_space, shape->getCPShape(),
                      (cpSpaceShapeQueryFunc)shapeQueryCallback, &context);
    return context.count;
}

float PhysicsShapeQuery::distanceBetweenShapes(PhysicsShape* shapeA, PhysicsShape* shapeB,
                                               Vec2* closestA, Vec2* closestB)
{
    if (!_initialized || shapeA == nullptr || shapeB == nullptr ||
        shapeA->getCPShape() == nullptr || shapeB->getCPShape() == nullptr)
    {
        return FLT_MAX;
    }

    cpShape* a = shapeA->getCPShape();
    cpShape* b = shapeB->getCPShape();

    // Overlapping shapes: report the contact points and zero distance.
    cpContactPointSet points = cpShapesCollide(a, b);
    if (points.count > 0)
    {
        if (closestA != nullptr)
        {
            *closestA = PhysicsHelper::cpv2point(points.points[0].pointA);
        }
        if (closestB != nullptr)
        {
            *closestB = PhysicsHelper::cpv2point(points.points[0].pointB);
        }
        return 0.0f;
    }

    // Separated shapes: approximate the gap with nearest-point queries from
    // each shape's center of gravity towards the other shape.
    cpVect centerA = cpShapeGetCenterOfGravity(a);
    cpVect centerB = cpShapeGetCenterOfGravity(b);

    cpPointQueryInfo infoA;
    cpPointQueryInfo infoB;
    cpShapePointQuery(a, centerB, &infoA); // point on A nearest to B's center
    cpShapePointQuery(b, centerA, &infoB); // point on B nearest to A's center

    // Refine: query B with the nearest point found on A and vice versa.
    cpPointQueryInfo refinedA;
    cpPointQueryInfo refinedB;
    cpShapePointQuery(a, infoB.point, &refinedA);
    cpShapePointQuery(b, infoA.point, &refinedB);

    float distA = static_cast<float>(cpvdist(refinedA.point, infoB.point));
    float distB = static_cast<float>(cpvdist(refinedB.point, infoA.point));

    if (distA <= distB)
    {
        if (closestA != nullptr)
        {
            *closestA = PhysicsHelper::cpv2point(refinedA.point);
        }
        if (closestB != nullptr)
        {
            *closestB = PhysicsHelper::cpv2point(infoB.point);
        }
        return distA;
    }

    if (closestA != nullptr)
    {
        *closestA = PhysicsHelper::cpv2point(infoA.point);
    }
    if (closestB != nullptr)
    {
        *closestB = PhysicsHelper::cpv2point(refinedB.point);
    }
    return distB;
}

bool PhysicsShapeQuery::containsPointInShape(PhysicsShape* shape, const Vec2& point, float* distance)
{
    if (!_initialized || shape == nullptr || shape->getCPShape() == nullptr)
    {
        return false;
    }

    cpPointQueryInfo info;
    cpFloat dist = cpShapePointQuery(shape->getCPShape(), PhysicsHelper::point2cpv(point), &info);
    if (distance != nullptr)
    {
        *distance = static_cast<float>(dist);
    }
    // Chipmunk reports a negative distance for points inside the shape.
    return dist <= 0.0f;
}

SweepResult PhysicsShapeQuery::sweepTest(PhysicsShape* shape, const Vec2& direction, float distance)
{
    SweepResult result = {};
    result.t = 1.0f;
    result.hit = false;

    if (!_initialized || _space == nullptr || shape == nullptr ||
        shape->getCPShape() == nullptr || distance <= 0.0f || direction.isZero())
    {
        return result;
    }

    cpVect pos = cpBodyGetPosition(cpShapeGetBody(shape->getCPShape()));
    Vec2 start = PhysicsHelper::cpv2point(pos) + shape->getCenter();
    Vec2 end = start + direction.getNormalized() * distance;

    // Capsule-cast approximation: inflate the swept path by the shape's
    // bounding radius so the segment query behaves like a moving shape.
    float radius = shapeBoundingRadius(shape);

    CollectShapesContext collectContext = { nullptr, 0, 0 };
    cpSegmentQueryInfo info;
    cpShape* hitShape = cpSpaceSegmentQueryFirst(_space,
                                                 PhysicsHelper::point2cpv(start),
                                                 PhysicsHelper::point2cpv(end),
                                                 radius,
                                                 CP_SHAPE_FILTER_ALL,
                                                 &info);
    (void)collectContext;

    if (hitShape != nullptr)
    {
        PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(hitShape));
        if (physicsShape != nullptr && physicsShape != shape)
        {
            result.shape = physicsShape;
            result.hitPoint = PhysicsHelper::cpv2point(info.point);
            result.hitNormal = PhysicsHelper::cpv2point(info.normal);
            result.t = static_cast<float>(info.alpha);
            result.hit = true;
        }
    }
    return result;
}

SweepResult PhysicsShapeQuery::castShape(PhysicsShape* shape, const Vec2& start, const Vec2& end)
{
    SweepResult result = {};
    result.t = 1.0f;
    result.hit = false;

    if (!_initialized || _space == nullptr || shape == nullptr ||
        shape->getCPShape() == nullptr || start == end)
    {
        return result;
    }

    float radius = shapeBoundingRadius(shape);

    cpSegmentQueryInfo info;
    cpShape* hitShape = cpSpaceSegmentQueryFirst(_space,
                                                 PhysicsHelper::point2cpv(start),
                                                 PhysicsHelper::point2cpv(end),
                                                 radius,
                                                 CP_SHAPE_FILTER_ALL,
                                                 &info);
    if (hitShape != nullptr)
    {
        PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(hitShape));
        if (physicsShape != nullptr && physicsShape != shape)
        {
            result.shape = physicsShape;
            result.hitPoint = PhysicsHelper::cpv2point(info.point);
            result.hitNormal = PhysicsHelper::cpv2point(info.normal);
            result.t = static_cast<float>(info.alpha);
            result.hit = true;
        }
    }
    return result;
}

Rect PhysicsShapeQuery::getShapeBoundingBox(PhysicsShape* shape) const
{
    if (shape == nullptr || shape->getCPShape() == nullptr)
    {
        return Rect::ZERO;
    }
    return PhysicsHelper::cpbb2rect(cpShapeGetBB(shape->getCPShape()));
}

Vec2 PhysicsShapeQuery::getShapeSurfaceVelocity(PhysicsShape* shape) const
{
    if (shape == nullptr || shape->getCPShape() == nullptr)
    {
        return Vec2::ZERO;
    }
    return PhysicsHelper::cpv2point(cpShapeGetSurfaceVelocity(shape->getCPShape()));
}

ShapeMassProperties PhysicsShapeQuery::computeShapeMassProperties(PhysicsShape* shape) const
{
    ShapeMassProperties props = {};
    if (shape == nullptr || shape->getCPShape() == nullptr)
    {
        return props;
    }

    cpShape* cpShapePtr = shape->getCPShape();
    props.mass = static_cast<float>(cpShapeGetMass(cpShapePtr));
    props.moment = static_cast<float>(cpShapeGetMoment(cpShapePtr));
    props.area = static_cast<float>(cpShapeGetArea(cpShapePtr));
    props.centerOfMass = PhysicsHelper::cpv2point(cpShapeGetCenterOfGravity(cpShapePtr));
    return props;
}

int PhysicsShapeQuery::batchOverlapTest(PhysicsShape** shapes, int count,
                                        bool* results, int maxResults)
{
    if (shapes == nullptr || results == nullptr || count < 2 || maxResults <= 0)
    {
        return 0;
    }

    // Shapes are supplied as consecutive pairs: (0,1), (2,3), ...
    int pairCount = count / 2;
    int tested = 0;
    for (int i = 0; i < pairCount && tested < maxResults; ++i)
    {
        results[tested++] = overlapTest(shapes[2 * i], shapes[2 * i + 1], nullptr, nullptr);
    }
    return tested;
}

int PhysicsShapeQuery::findShapesInRect(const Rect& rect, PhysicsShape** results, int maxResults)
{
    if (!_initialized || _space == nullptr || results == nullptr || maxResults <= 0)
    {
        return 0;
    }

    CollectShapesContext context = { results, maxResults, 0 };
    cpSpaceBBQuery(_space, PhysicsHelper::rect2cpbb(rect), CP_SHAPE_FILTER_ALL,
                   (cpSpaceBBQueryFunc)collectShapeCallback, &context);
    return context.count;
}

int PhysicsShapeQuery::findShapesAtPoint(const Vec2& point, PhysicsShape** results, int maxResults)
{
    if (!_initialized || _space == nullptr || results == nullptr || maxResults <= 0)
    {
        return 0;
    }

    CollectShapesContext context = { results, maxResults, 0 };
    cpSpacePointQuery(_space, PhysicsHelper::point2cpv(point), 0.0f, CP_SHAPE_FILTER_ALL,
                      (cpSpacePointQueryFunc)collectPointCallback, &context);
    return context.count;
}

int PhysicsShapeQuery::findShapesAlongSegment(const Vec2& start, const Vec2& end, float radius,
                                              PhysicsShape** results, int maxResults)
{
    if (!_initialized || _space == nullptr || results == nullptr || maxResults <= 0)
    {
        return 0;
    }

    CollectShapesContext context = { results, maxResults, 0 };
    cpSpaceSegmentQuery(_space, PhysicsHelper::point2cpv(start), PhysicsHelper::point2cpv(end),
                        radius < 0.0f ? 0.0f : radius, CP_SHAPE_FILTER_ALL,
                        (cpSpaceSegmentQueryFunc)collectSegmentCallback, &context);
    return context.count;
}

float PhysicsShapeQuery::computeCircleArea(float radius) const
{
    return PhysicsHelper::circleArea(radius);
}

float PhysicsShapeQuery::computePolygonArea(const Vec2* verts, int count) const
{
    return PhysicsHelper::polygonArea(verts, count);
}

float PhysicsShapeQuery::computeSegmentArea(const Vec2& a, const Vec2& b, float radius) const
{
    // Capsule area: rectangle swept by the segment plus the two end caps.
    float length = a.distance(b);
    return radius * (static_cast<float>(M_PI) * radius + 2.0f * length);
}

float PhysicsShapeQuery::computeCircleMoment(float mass, float radius, const Vec2& offset) const
{
    return PhysicsHelper::circleMoment(mass, radius, offset);
}

float PhysicsShapeQuery::computePolygonMoment(float mass, const Vec2* verts, int count, const Vec2& offset) const
{
    return PhysicsHelper::polygonMoment(mass, verts, count, offset);
}

float PhysicsShapeQuery::computeSegmentMoment(float mass, const Vec2& a, const Vec2& b, float radius) const
{
    // Approximate the capsule as a box of (length + 2r) x (2r) centered on the
    // segment midpoint, plus the parallel-axis contribution of the midpoint.
    Vec2 mid = (a + b) * 0.5f;
    float length = a.distance(b) + 2.0f * radius;
    float height = 2.0f * radius;
    return mass * ((length * length + height * height) / 12.0f + mid.getLengthSq());
}

NS_CC_END

#endif // CC_USE_PHYSICS

