#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    // Build a chipmunk query filter from a category mask: only shapes whose
    // own categories intersect the mask are reported.
    cpShapeFilter filterForCategoryMask(unsigned int categoryMask)
    {
        return cpShapeFilterNew(CP_NO_GROUP, CP_ALL_CATEGORIES, categoryMask);
    }

    PhysicsShape* shapeFromCpShape(cpShape* shape)
    {
        return shape != nullptr ? static_cast<PhysicsShape*>(cpShapeGetUserData(shape)) : nullptr;
    }

    struct SegmentQueryContext
    {
        std::vector<PhysicsSegmentQueryResult>* results;
    };

    void segmentQueryCallback(cpShape* shape, cpVect point, cpVect normal, cpFloat alpha, void* data)
    {
        auto* context = static_cast<SegmentQueryContext*>(data);
        PhysicsShape* physicsShape = shapeFromCpShape(shape);
        if (context == nullptr || physicsShape == nullptr)
        {
            return;
        }

        PhysicsSegmentQueryResult result;
        result.shape = physicsShape;
        result.point = PhysicsHelper::cpv2point(point);
        result.normal = PhysicsHelper::cpv2point(normal);
        result.alpha = static_cast<float>(alpha);
        context->results->push_back(result);
    }

    struct BBQueryContext
    {
        std::vector<PhysicsBBQueryResult>* results;
    };

    void bbQueryCallback(cpShape* shape, void* data)
    {
        auto* context = static_cast<BBQueryContext*>(data);
        PhysicsShape* physicsShape = shapeFromCpShape(shape);
        if (context == nullptr || physicsShape == nullptr)
        {
            return;
        }

        PhysicsBBQueryResult result;
        result.shape = physicsShape;
        context->results->push_back(result);
    }

    struct PointQueryContext
    {
        std::vector<PhysicsNearestResult>* results;
    };

    void pointQueryCallback(cpShape* shape, cpVect point, cpFloat distance, cpVect gradient, void* data)
    {
        auto* context = static_cast<PointQueryContext*>(data);
        PhysicsShape* physicsShape = shapeFromCpShape(shape);
        if (context == nullptr || physicsShape == nullptr)
        {
            return;
        }

        PhysicsNearestResult result;
        result.shape = physicsShape;
        result.point = PhysicsHelper::cpv2point(point);
        result.distance = static_cast<float>(distance);
        result.gradient = PhysicsHelper::cpv2point(gradient);
        context->results->push_back(result);
    }

    struct CollectBodiesContext
    {
        std::unordered_set<cpShape*>* seen;
        std::vector<PhysicsBody*>* bodies;
    };

    void collectBodyFromShape(cpShape* shape, CollectBodiesContext* context)
    {
        if (context == nullptr || shape == nullptr || !context->seen->insert(shape).second)
        {
            return;
        }
        PhysicsShape* physicsShape = shapeFromCpShape(shape);
        if (physicsShape != nullptr && physicsShape->getBody() != nullptr)
        {
            context->bodies->push_back(physicsShape->getBody());
        }
    }

    void collectBodiesBBCallback(cpShape* shape, void* data)
    {
        collectBodyFromShape(shape, static_cast<CollectBodiesContext*>(data));
    }

    void collectBodiesSegmentCallback(cpShape* shape, cpVect /*point*/, cpVect /*normal*/,
                                      cpFloat /*alpha*/, void* data)
    {
        collectBodyFromShape(shape, static_cast<CollectBodiesContext*>(data));
    }

    void collectBodiesPointCallback(cpShape* shape, cpVect /*point*/, cpFloat /*distance*/,
                                    cpVect /*gradient*/, void* data)
    {
        collectBodyFromShape(shape, static_cast<CollectBodiesContext*>(data));
    }

    struct ArbiterContext
    {
        std::vector<PhysicsContactPairInfo>* contacts;
    };

    void arbiterCallback(cpArbiter* arbiter, void* data)
    {
        auto* context = static_cast<ArbiterContext*>(data);
        if (context == nullptr || arbiter == nullptr || !cpArbiterIsFirstContact(arbiter))
        {
            return;
        }

        cpBody* bodyA = nullptr;
        cpBody* bodyB = nullptr;
        cpArbiterGetBodies(arbiter, &bodyA, &bodyB);

        cpContactPointSet points = cpArbiterGetContactPointSet(arbiter);
        if (points.count <= 0)
        {
            return;
        }

        PhysicsContactPairInfo info;
        info.bodyA = bodyA != nullptr ? static_cast<PhysicsBody*>(cpBodyGetUserData(bodyA)) : nullptr;
        info.bodyB = bodyB != nullptr ? static_cast<PhysicsBody*>(cpBodyGetUserData(bodyB)) : nullptr;
        info.contactPoint = PhysicsHelper::cpv2point(points.points[0].pointA);
        info.contactNormal = PhysicsHelper::cpv2point(points.normal);
        info.penetration = -static_cast<float>(points.points[0].distance);
        context->contacts->push_back(info);
    }
}

PhysicsWorldQuery::PhysicsWorldQuery()
: _space(nullptr)
, _initialized(false)
{
}

PhysicsWorldQuery::~PhysicsWorldQuery()
{
}

bool PhysicsWorldQuery::init(cpSpace* space)
{
    if (space == nullptr)
    {
        return false;
    }

    _space = space;
    _initialized = true;
    return true;
}

PhysicsNearestResult PhysicsWorldQuery::queryNearestPoint(const Vec2& point, float maxDistance, unsigned int categoryMask)
{
    PhysicsNearestResult result = { nullptr, Vec2::ZERO, 0.0f, Vec2::ZERO };
    if (!_initialized)
    {
        return result;
    }

    cpPointQueryInfo info;
    cpShape* shape = cpSpacePointQueryNearest(_space, PhysicsHelper::point2cpv(point),
                                              maxDistance < 0.0f ? 0.0f : maxDistance,
                                              filterForCategoryMask(categoryMask), &info);
    if (shape != nullptr)
    {
        result.shape = shapeFromCpShape(shape);
        result.point = PhysicsHelper::cpv2point(info.point);
        result.distance = static_cast<float>(info.distance);
        result.gradient = PhysicsHelper::cpv2point(info.gradient);
    }
    return result;
}

std::vector<PhysicsSegmentQueryResult> PhysicsWorldQuery::querySegment(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
{
    std::vector<PhysicsSegmentQueryResult> results;
    if (!_initialized)
    {
        return results;
    }

    SegmentQueryContext context = { &results };
    cpSpaceSegmentQuery(_space, PhysicsHelper::point2cpv(start), PhysicsHelper::point2cpv(end),
                        radius < 0.0f ? 0.0f : radius, filterForCategoryMask(categoryMask),
                        (cpSpaceSegmentQueryFunc)segmentQueryCallback, &context);

    // Nearest hits first, stable for equal fractions.
    std::stable_sort(results.begin(), results.end(),
                     [](const PhysicsSegmentQueryResult& a, const PhysicsSegmentQueryResult& b)
                     {
                         return a.alpha < b.alpha;
                     });
    return results;
}

PhysicsSegmentQueryResult PhysicsWorldQuery::querySegmentFirst(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
{
    PhysicsSegmentQueryResult result = { nullptr, Vec2::ZERO, Vec2::ZERO, 1.0f };
    if (!_initialized)
    {
        return result;
    }

    cpSegmentQueryInfo info;
    cpShape* shape = cpSpaceSegmentQueryFirst(_space, PhysicsHelper::point2cpv(start),
                                              PhysicsHelper::point2cpv(end),
                                              radius < 0.0f ? 0.0f : radius,
                                              filterForCategoryMask(categoryMask), &info);
    if (shape != nullptr)
    {
        result.shape = shapeFromCpShape(shape);
        result.point = PhysicsHelper::cpv2point(info.point);
        result.normal = PhysicsHelper::cpv2point(info.normal);
        result.alpha = static_cast<float>(info.alpha);
    }
    return result;
}

std::vector<PhysicsBBQueryResult> PhysicsWorldQuery::queryBoundingBox(const Rect& rect, unsigned int categoryMask)
{
    std::vector<PhysicsBBQueryResult> results;
    if (!_initialized)
    {
        return results;
    }

    BBQueryContext context = { &results };
    cpSpaceBBQuery(_space, PhysicsHelper::rect2cpbb(rect), filterForCategoryMask(categoryMask),
                   (cpSpaceBBQueryFunc)bbQueryCallback, &context);
    return results;
}

std::vector<PhysicsNearestResult> PhysicsWorldQuery::queryPointAll(const Vec2& point, float maxDistance, unsigned int categoryMask)
{
    std::vector<PhysicsNearestResult> results;
    if (!_initialized)
    {
        return results;
    }

    PointQueryContext context = { &results };
    cpSpacePointQuery(_space, PhysicsHelper::point2cpv(point),
                      maxDistance < 0.0f ? 0.0f : maxDistance, filterForCategoryMask(categoryMask),
                      (cpSpacePointQueryFunc)pointQueryCallback, &context);

    std::stable_sort(results.begin(), results.end(),
                     [](const PhysicsNearestResult& a, const PhysicsNearestResult& b)
                     {
                         return a.distance < b.distance;
                     });
    return results;
}

int PhysicsWorldQuery::countBodiesInRect(const Rect& rect, unsigned int categoryMask)
{
    if (!_initialized)
    {
        return 0;
    }

    std::unordered_set<cpShape*> seen;
    std::vector<PhysicsBody*> bodies;
    CollectBodiesContext context = { &seen, &bodies };
    cpSpaceBBQuery(_space, PhysicsHelper::rect2cpbb(rect), filterForCategoryMask(categoryMask),
                   (cpSpaceBBQueryFunc)collectBodiesBBCallback, &context);
    return static_cast<int>(bodies.size());
}

bool PhysicsWorldQuery::isPointOccupied(const Vec2& point, unsigned int categoryMask)
{
    if (!_initialized)
    {
        return false;
    }

    cpShape* shape = cpSpacePointQueryNearest(_space, PhysicsHelper::point2cpv(point), 0.0f,
                                              filterForCategoryMask(categoryMask), nullptr);
    return shape != nullptr;
}

float PhysicsWorldQuery::distanceToNearestBody(const Vec2& point, unsigned int categoryMask)
{
    PhysicsNearestResult nearest = queryNearestPoint(point, FLT_MAX, categoryMask);
    return nearest.shape != nullptr ? nearest.distance : -1.0f;
}

std::vector<PhysicsContactPairInfo> PhysicsWorldQuery::getActiveContacts()
{
    std::vector<PhysicsContactPairInfo> contacts;
    if (!_initialized)
    {
        return contacts;
    }

    ArbiterContext context = { &contacts };
    cpSpaceEachCachedArbiter(_space, (cpSpaceArbiterIteratorFunc)arbiterCallback, &context);
    return contacts;
}

std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesAlongRay(const Vec2& start, const Vec2& end, unsigned int categoryMask)
{
    std::vector<PhysicsBody*> bodies;
    if (!_initialized)
    {
        return bodies;
    }

    std::unordered_set<cpShape*> seen;
    CollectBodiesContext context = { &seen, &bodies };
    cpSpaceSegmentQuery(_space, PhysicsHelper::point2cpv(start), PhysicsHelper::point2cpv(end),
                        0.0f, filterForCategoryMask(categoryMask),
                        (cpSpaceSegmentQueryFunc)collectBodiesSegmentCallback, &context);
    return bodies;
}

PhysicsBody* PhysicsWorldQuery::getBodyAtPoint(const Vec2& point)
{
    if (!_initialized)
    {
        return nullptr;
    }

    cpShape* shape = cpSpacePointQueryNearest(_space, PhysicsHelper::point2cpv(point), 0.0f,
                                              CP_SHAPE_FILTER_ALL, nullptr);
    PhysicsShape* physicsShape = shapeFromCpShape(shape);
    return physicsShape != nullptr ? physicsShape->getBody() : nullptr;
}

std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesInCircle(const Vec2& center, float radius, unsigned int categoryMask)
{
    std::vector<PhysicsBody*> bodies;
    if (!_initialized || radius < 0.0f)
    {
        return bodies;
    }

    std::unordered_set<cpShape*> seen;
    CollectBodiesContext context = { &seen, &bodies };
    cpSpacePointQuery(_space, PhysicsHelper::point2cpv(center), radius,
                      filterForCategoryMask(categoryMask),
                      (cpSpacePointQueryFunc)collectBodiesPointCallback, &context);
    return bodies;
}

bool PhysicsWorldQuery::lineOfSight(const Vec2& start, const Vec2& end, unsigned int blockMask)
{
    if (!_initialized)
    {
        return true;
    }

    cpShape* blocker = cpSpaceSegmentQueryFirst(_space, PhysicsHelper::point2cpv(start),
                                                PhysicsHelper::point2cpv(end), 0.0f,
                                                filterForCategoryMask(blockMask), nullptr);
    return blocker == nullptr;
}

float PhysicsWorldQuery::computePathClearance(const Vec2* path, int pathCount, unsigned int blockMask)
{
    if (!_initialized || path == nullptr || pathCount < 2)
    {
        return 0.0f;
    }

    // Clearance is the shortest free travel distance along the path before a
    // blocking shape is encountered; a fully clear segment counts full length.
    float clearance = FLT_MAX;
    for (int i = 0; i + 1 < pathCount; ++i)
    {
        Vec2 a = path[i];
        Vec2 b = path[i + 1];
        float segmentLength = a.distance(b);

        cpSegmentQueryInfo info;
        cpShape* blocker = cpSpaceSegmentQueryFirst(_space, PhysicsHelper::point2cpv(a),
                                                    PhysicsHelper::point2cpv(b), 0.0f,
                                                    filterForCategoryMask(blockMask), &info);
        float freeLength = blocker != nullptr ? static_cast<float>(info.alpha) * segmentLength
                                              : segmentLength;
        clearance = std::min(clearance, freeLength);
    }
    return clearance == FLT_MAX ? 0.0f : clearance;
}

std::vector<Vec2> PhysicsWorldQuery::findOpenPositions(const Rect& searchArea, float spacing, float clearance, unsigned int blockMask)
{
    std::vector<Vec2> positions;
    if (!_initialized || spacing <= 0.0f)
    {
        return positions;
    }

    for (float y = searchArea.getMinY(); y <= searchArea.getMaxY() + 1e-4f; y += spacing)
    {
        for (float x = searchArea.getMinX(); x <= searchArea.getMaxX() + 1e-4f; x += spacing)
        {
            Vec2 candidate(x, y);
            cpShape* blocker = cpSpacePointQueryNearest(_space, PhysicsHelper::point2cpv(candidate),
                                                        clearance < 0.0f ? 0.0f : clearance,
                                                        filterForCategoryMask(blockMask), nullptr);
            if (blocker == nullptr)
            {
                positions.push_back(candidate);
            }
        }
    }
    return positions;
}

