#include "physics/CCPhysicsDebugDraw.h"
#if CC_USE_PHYSICS

#include <cmath>
#include <vector>
#include "2d/CCDrawNode.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsJoint.h"
#include "physics/CCPhysicsWorld.h"
#include "physics/CCPhysicsHelper.h"

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

NS_CC_BEGIN

namespace
{
    const int CIRCLE_SEGMENTS = 24;

    Color4F dimmed(const Color4F& color, float factor)
    {
        return Color4F(color.r * factor, color.g * factor, color.b * factor, color.a);
    }
}

PhysicsDebugDraw::PhysicsDebugDraw()
: _drawNode(nullptr)
, _initialized(false)
{
    _config.drawShapes = true;
    _config.drawJoints = true;
    _config.drawContacts = false;
    _config.drawBoundingBoxes = false;
    _config.drawCentersOfMass = false;
    _config.drawVelocities = false;
    _config.drawSleepState = false;
    _config.shapeColor = Color4F(0.0f, 1.0f, 0.0f, 0.5f);
    _config.jointColor = Color4F(0.0f, 0.0f, 1.0f, 0.8f);
    _config.contactColor = Color4F(1.0f, 0.0f, 0.0f, 1.0f);
    _config.bbColor = Color4F(1.0f, 1.0f, 0.0f, 0.3f);
    _config.lineWidth = 1.0f;
}

PhysicsDebugDraw::~PhysicsDebugDraw()
{
}

bool PhysicsDebugDraw::init(DrawNode* drawNode)
{
    if (drawNode == nullptr)
    {
        return false;
    }

    _drawNode = drawNode;
    _initialized = true;
    return true;
}

void PhysicsDebugDraw::setConfig(const PhysicsDebugDrawConfig& config)
{
    _config = config;
}

PhysicsDebugDrawConfig PhysicsDebugDraw::getConfig() const
{
    return _config;
}

void PhysicsDebugDraw::beginDraw()
{
    // Retained DrawNode accumulates primitives: reset before a new frame.
    if (_initialized && _drawNode != nullptr)
    {
        _drawNode->clear();
    }
}

void PhysicsDebugDraw::endDraw()
{
    // Nothing to flush: DrawNode primitives are retained until clear().
}

void PhysicsDebugDraw::clear()
{
    if (_initialized && _drawNode != nullptr)
    {
        _drawNode->clear();
    }
}

void PhysicsDebugDraw::drawWorld(PhysicsWorld* world)
{
    if (!_initialized || world == nullptr)
    {
        return;
    }

    for (auto body : world->getAllBodies())
    {
        if (body == nullptr)
        {
            continue;
        }

        drawBody(body);

        // Draw each joint exactly once: only from its body A side.
        if (_config.drawJoints)
        {
            for (auto joint : body->getJoints())
            {
                if (joint != nullptr && joint->getBodyA() == body)
                {
                    drawJoint(joint);
                }
            }
        }
    }
}

void PhysicsDebugDraw::drawBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr)
    {
        return;
    }

    if (_config.drawShapes)
    {
        for (auto shape : body->getShapes())
        {
            drawShape(shape);
        }
    }

    if (_config.drawBoundingBoxes)
    {
        // Union of the per-shape world AABBs.
        Rect bb;
        bool first = true;
        for (auto shape : body->getShapes())
        {
            if (shape == nullptr)
            {
                continue;
            }

            Rect shapeBB;
            switch (shape->getType())
            {
                case PhysicsShape::Type::CIRCLE:
                {
                    auto* circle = static_cast<PhysicsShapeCircle*>(shape);
                    Vec2 center = body->local2World(circle->getOffset());
                    float r = circle->getRadius();
                    shapeBB = Rect(center.x - r, center.y - r, 2.0f * r, 2.0f * r);
                    break;
                }
                case PhysicsShape::Type::POLYGEN:
                case PhysicsShape::Type::BOX:
                {
                    auto* poly = static_cast<PhysicsShapePolygon*>(shape);
                    int count = poly->getPointsCount();
                    if (count > 0)
                    {
                        Vec2 p = body->local2World(poly->getPoint(0));
                        float minX = p.x, minY = p.y, maxX = p.x, maxY = p.y;
                        for (int i = 1; i < count; ++i)
                        {
                            p = body->local2World(poly->getPoint(i));
                            minX = std::min(minX, p.x);
                            minY = std::min(minY, p.y);
                            maxX = std::max(maxX, p.x);
                            maxY = std::max(maxY, p.y);
                        }
                        shapeBB = Rect(minX, minY, maxX - minX, maxY - minY);
                    }
                    break;
                }
                default:
                    continue;
            }

            bb = first ? shapeBB : bb.unionWithRect(shapeBB);
            first = false;
        }

        if (!first)
        {
            drawBoundingBox(bb, _config.bbColor);
        }
    }

    if (_config.drawVelocities && body->isDynamic())
    {
        drawVelocityVector(body->getPosition(), body->getVelocity(), Color4F::WHITE);
    }

    if (_config.drawCentersOfMass)
    {
        drawCenterOfMass(body->getPosition(), 3.0f, Color4F::MAGENTA);
    }

    if (_config.drawSleepState)
    {
        drawSleepIndicator(body->getPosition(), body->isResting(), _config.shapeColor);
    }
}

void PhysicsDebugDraw::drawShape(PhysicsShape* shape)
{
    if (!_initialized || shape == nullptr || shape->getBody() == nullptr)
    {
        return;
    }

    PhysicsBody* body = shape->getBody();
    Color4F color = getShapeColor(shape);
    Color4F outline(color.r, color.g, color.b, 1.0f);

    switch (shape->getType())
    {
        case PhysicsShape::Type::CIRCLE:
        {
            auto* circle = static_cast<PhysicsShapeCircle*>(shape);
            Vec2 center = body->local2World(circle->getOffset());
            float angle = -CC_DEGREES_TO_RADIANS(body->getRotation());
            drawCircleShape(center, circle->getRadius(), angle, color, outline);
            break;
        }
        case PhysicsShape::Type::POLYGEN:
        case PhysicsShape::Type::BOX:
        case PhysicsShape::Type::EDGEPOLYGEN:
        case PhysicsShape::Type::EDGEBOX:
        {
            auto* poly = static_cast<PhysicsShapePolygon*>(shape);
            int count = poly->getPointsCount();
            if (count >= 3)
            {
                std::vector<Vec2> verts(static_cast<size_t>(count));
                for (int i = 0; i < count; ++i)
                {
                    verts[static_cast<size_t>(i)] = body->local2World(poly->getPoint(i));
                }
                drawPolygonShape(verts.data(), count, color, outline);
            }
            break;
        }
        case PhysicsShape::Type::EDGESEGMENT:
        {
            auto* segment = static_cast<PhysicsShapeEdgeSegment*>(shape);
            Vec2 a = body->local2World(segment->getPointA());
            Vec2 b = body->local2World(segment->getPointB());
            drawSegmentShape(a, b, _config.lineWidth, outline);
            break;
        }
        default:
            break;
    }
}

void PhysicsDebugDraw::drawJoint(PhysicsJoint* joint)
{
    if (!_initialized || joint == nullptr || joint->getBodyA() == nullptr || joint->getBodyB() == nullptr)
    {
        return;
    }

    PhysicsBody* bodyA = joint->getBodyA();
    PhysicsBody* bodyB = joint->getBodyB();
    Color4F color = _config.jointColor;

    if (auto* spring = dynamic_cast<PhysicsJointSpring*>(joint))
    {
        Vec2 anchorA = bodyA->local2World(spring->getAnchr1());
        Vec2 anchorB = bodyB->local2World(spring->getAnchr2());
        drawSpringJoint(anchorA, anchorB, spring->getRestLength(), color);
    }
    else if (auto* limit = dynamic_cast<PhysicsJointLimit*>(joint))
    {
        Vec2 anchorA = bodyA->local2World(limit->getAnchr1());
        Vec2 anchorB = bodyB->local2World(limit->getAnchr2());
        drawSlideJoint(anchorA, anchorB, limit->getMin(), limit->getMax(), color);
    }
    else if (auto* distance = dynamic_cast<PhysicsJointDistance*>(joint))
    {
        // Fixed-distance constraint: render like a slide joint with min == max.
        drawSlideJoint(bodyA->getPosition(), bodyB->getPosition(),
                       distance->getDistance(), distance->getDistance(), color);
    }
    else
    {
        // Pin, fixed, groove, rotary and gear variants share the basic
        // two-anchor rendering between the body positions.
        drawPinJoint(bodyA->getPosition(), bodyB->getPosition(), color);
    }
}

void PhysicsDebugDraw::drawCircleShape(const Vec2& center, float radius, float angle,
                                       const Color4F& fillColor, const Color4F& outlineColor)
{
    if (!_initialized)
    {
        return;
    }

    _drawNode->drawCircle(center, radius, angle, CIRCLE_SEGMENTS, true, _config.lineWidth, 1.0f, outlineColor);

    // Translucent fill via a solid circle scaled just inside the outline.
    Color4F fill(fillColor.r, fillColor.g, fillColor.b, fillColor.a * 0.5f);
    _drawNode->drawSolidCircle(center, radius * 0.95f, angle, CIRCLE_SEGMENTS, 1.0f, 1.0f, fill);
}

void PhysicsDebugDraw::drawPolygonShape(const Vec2* verts, int count,
                                        const Color4F& fillColor, const Color4F& outlineColor)
{
    if (!_initialized || verts == nullptr || count < 3)
    {
        return;
    }

    _drawNode->drawPolygon(verts, count, fillColor, _config.lineWidth, outlineColor);
}

void PhysicsDebugDraw::drawSegmentShape(const Vec2& a, const Vec2& b, float radius,
                                        const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    _drawNode->drawSegment(a, b, radius > 0.0f ? radius : 0.5f, color);
}

void PhysicsDebugDraw::drawBoundingBox(const Rect& bb, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    Vec2 origin(bb.getMinX(), bb.getMinY());
    Vec2 destination(bb.getMaxX(), bb.getMaxY());
    _drawNode->drawRect(origin, destination, color);
}

void PhysicsDebugDraw::drawContactPoint(const Vec2& point, const Vec2& normal, float depth,
                                        const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    _drawNode->drawDot(point, 2.0f, color);
    Vec2 scaled = normal.isZero() ? Vec2::ZERO : normal.getNormalized() * (4.0f + std::fabs(depth) * 4.0f);
    _drawNode->drawLine(point, point + scaled, color);
}

void PhysicsDebugDraw::drawVelocityVector(const Vec2& pos, const Vec2& vel, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    Vec2 tip = pos + vel;
    _drawNode->drawLine(pos, tip, color);

    // Arrow head.
    if (!vel.isZero())
    {
        Vec2 dir = vel.getNormalized();
        Vec2 left(-dir.y, dir.x);
        float headLen = std::min(6.0f, vel.getLength() * 0.25f);
        _drawNode->drawLine(tip, tip - dir * headLen + left * headLen * 0.5f, color);
        _drawNode->drawLine(tip, tip - dir * headLen - left * headLen * 0.5f, color);
    }
}

void PhysicsDebugDraw::drawCenterOfMass(const Vec2& pos, float radius, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    _drawNode->drawLine(pos - Vec2(radius, 0.0f), pos + Vec2(radius, 0.0f), color);
    _drawNode->drawLine(pos - Vec2(0.0f, radius), pos + Vec2(0.0f, radius), color);
    _drawNode->drawCircle(pos, radius, 0.0f, CIRCLE_SEGMENTS, false, 1.0f, 1.0f, color);
}

void PhysicsDebugDraw::drawSleepIndicator(const Vec2& pos, bool sleeping, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    // Sleeping bodies get a small dimmed square above the origin.
    Color4F c = sleeping ? dimmed(color, 0.4f) : color;
    float s = 3.0f;
    Vec2 base = pos + Vec2(0.0f, 8.0f);
    _drawNode->drawRect(base - Vec2(s, s), base + Vec2(s, s), c);
}

void PhysicsDebugDraw::drawPinJoint(const Vec2& anchorA, const Vec2& anchorB, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    _drawNode->drawLine(anchorA, anchorB, color);
    _drawNode->drawDot(anchorA, 2.0f, color);
    _drawNode->drawDot(anchorB, 2.0f, color);
}

void PhysicsDebugDraw::drawSpringJoint(const Vec2& anchorA, const Vec2& anchorB,
                                       float restLength, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    // Zig-zag coil between the anchors.
    Vec2 axis = anchorB - anchorA;
    float length = axis.getLength();
    if (length < 1e-6f)
    {
        _drawNode->drawDot(anchorA, 2.0f, color);
        return;
    }

    Vec2 dir = axis / length;
    Vec2 perp(-dir.y, dir.x);
    float amplitude = std::min(4.0f, restLength * 0.1f);

    const int coils = 8;
    Vec2 prev = anchorA;
    for (int i = 1; i < coils; ++i)
    {
        float t = static_cast<float>(i) / static_cast<float>(coils);
        Vec2 p = anchorA + axis * t + perp * ((i % 2 == 0) ? amplitude : -amplitude);
        _drawNode->drawLine(prev, p, color);
        prev = p;
    }
    _drawNode->drawLine(prev, anchorB, color);
    _drawNode->drawDot(anchorA, 2.0f, color);
    _drawNode->drawDot(anchorB, 2.0f, color);
}

void PhysicsDebugDraw::drawSlideJoint(const Vec2& anchorA, const Vec2& anchorB,
                                      float minDist, float maxDist, const Color4F& color)
{
    if (!_initialized)
    {
        return;
    }

    _drawNode->drawLine(anchorA, anchorB, color);
    _drawNode->drawDot(anchorA, 2.0f, color);
    _drawNode->drawDot(anchorB, 2.0f, color);

    // Min/max travel rings around anchor A.
    if (minDist > 0.0f)
    {
        _drawNode->drawCircle(anchorA, minDist, 0.0f, CIRCLE_SEGMENTS, false, 1.0f, 1.0f, dimmed(color, 0.6f));
    }
    if (maxDist > minDist)
    {
        _drawNode->drawCircle(anchorA, maxDist, 0.0f, CIRCLE_SEGMENTS, false, 1.0f, 1.0f, dimmed(color, 0.3f));
    }
}

Color4F PhysicsDebugDraw::getShapeColor(PhysicsShape* shape) const
{
    Color4F color = _config.shapeColor;
    if (shape != nullptr)
    {
        if (shape->isSensor())
        {
            // Sensors are rendered in a distinct, translucent tone.
            color = Color4F(0.2f, 0.8f, 1.0f, color.a * 0.5f);
        }
        else if (shape->getBody() != nullptr)
        {
            color = getBodyColor(shape->getBody());
        }
    }
    return color;
}

Color4F PhysicsDebugDraw::getBodyColor(PhysicsBody* body) const
{
    Color4F color = _config.shapeColor;
    if (body != nullptr)
    {
        if (!body->isDynamic())
        {
            // Static / kinematic bodies: cooler tone.
            color = Color4F(0.5f, 0.5f, 0.9f, color.a);
        }
        else if (body->isResting())
        {
            color = dimmed(color, 0.5f);
        }
    }
    return color;
}

NS_CC_END

#endif // CC_USE_PHYSICS

